// Alzheimer's callout photo. Inlined as a data URI for the preview; in the
// Vite build this is replaced by <img src="/alzheimers.png" /> from public/.
const ALZHEIMERS_IMG = "data:image/png;base64,";

// Hero photo. Inlined as a data URI for the preview; in the Vite build this is
// replaced by <img src="/hero.png" /> from public/. Any width is fine — it is
// object-fit:cover cropped to fill the hero's full height.
const HERO_IMG = "data:image/png;base64,";

// Lightweight placeholder used in the preview only. In the real build these are
// replaced by /toolbar.png, /hero.png, and /alzheimers.png from public/.
function ImagePlaceholder({ label, dims, style }) {
  return (
    <div
      className="flex flex-col items-center justify-center text-center"
      style={{
        width: '100%',
        height: '100%',
        minHeight: '100%',
        background: 'repeating-linear-gradient(45deg, rgba(0,0,0,0.04) 0, rgba(0,0,0,0.04) 10px, rgba(0,0,0,0.07) 10px, rgba(0,0,0,0.07) 20px)',
        color: 'rgba(255,255,255,0.92)',
        ...style,
      }}
    >
      <div style={{ fontSize: '13px', fontWeight: 700, letterSpacing: '0.02em', mixBlendMode: 'normal' }}>{label}</div>
      {dims && <div style={{ fontSize: '11px', opacity: 0.75, marginTop: '2px' }}>{dims}</div>}
    </div>
  );
}

