export default function FairHealthPrototype() {
  const [conditionDropdownOpen, setConditionDropdownOpen] = useState(false);
  const [selectedCondition, setSelectedCondition] = useState(null);
  const [procedureDropdownOpen, setProcedureDropdownOpen] = useState(false);
  const [selectedProcedure, setSelectedProcedure] = useState(null);
  const [zipValue, setZipValue] = useState('');
  const [checklistDropdownOpen, setChecklistDropdownOpen] = useState(false);
  const [selectedChecklist, setSelectedChecklist] = useState(null);

  const conditionDropdownRef = useRef(null);
  const procedureDropdownRef = useRef(null);
  const checklistDropdownRef = useRef(null);

  // Close the condition dropdown when clicking outside.
  useEffect(() => {
    if (!conditionDropdownOpen) return;
    const handleClickOutside = (e) => {
      if (conditionDropdownRef.current && !conditionDropdownRef.current.contains(e.target)) {
        setConditionDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [conditionDropdownOpen]);

  // Close the procedure dropdown when clicking outside.
  useEffect(() => {
    if (!procedureDropdownOpen) return;
    const handleClickOutside = (e) => {
      if (procedureDropdownRef.current && !procedureDropdownRef.current.contains(e.target)) {
        setProcedureDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [procedureDropdownOpen]);

  // Close the checklist dropdown when clicking outside.
  useEffect(() => {
    if (!checklistDropdownOpen) return;
    const handleClickOutside = (e) => {
      if (checklistDropdownRef.current && !checklistDropdownRef.current.contains(e.target)) {
        setChecklistDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [checklistDropdownOpen]);

  return (
    <div className="min-h-screen w-full" style={{ background: '#E8EAF6', fontFamily: 'Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif' }}>

      {/* Explicit desktop sizing for the photo columns — does not rely on
          Tailwind arbitrary values, so it works in any environment. */}
      <style>{`
        @media (min-width: 768px) {
          .fh-hero-img { width: 360px; height: auto; flex-shrink: 0; }
          .fh-alz-img  { width: 202px; height: auto; flex-shrink: 0; }
        }
      `}</style>

      {/* === Top toolbar image ===
          When deploying to Netlify, place your header image at /toolbar.png in the public/
          folder (at 1222×72px). The image is contained at its native size on desktop and
          scales down gracefully on mobile. */}
      <div className="bg-white border-b" style={{ borderColor: '#E5E5E5' }}>
        <div className="max-w-6xl mx-auto">
          {/* PREVIEW PLACEHOLDER — replace with <img src="/toolbar.png" /> in the build */}
          <div style={{ width: '100%', maxWidth: '1222px', height: '72px' }}>
            <ImagePlaceholder label="toolbar.png" dims="1222 × 72" style={{ color: '#6b6b6b', background: '#EDEDED' }} />
          </div>
        </div>
      </div>

      {/* === Main content === */}
      <div className="max-w-6xl mx-auto px-4 md:px-6 py-6 space-y-6 md:space-y-7">

        {/* Hero */}
        <div className="bg-white overflow-hidden flex flex-col md:flex-row" style={{ border: '1px solid #E5E5E5' }}>
          <div className="flex-1 p-5 md:p-8">
            <div className="text-sm font-medium mb-2" style={{ color: '#0891B2' }}>FAIR Health for Older Adults</div>
            <h1 className="text-3xl md:text-4xl font-bold mb-3" style={{ color: '#141414', letterSpacing: '-0.02em' }}>Healthy Decisions for Healthy Aging</h1>
            <p className="text-base md:text-lg mb-6 md:mb-8" style={{ color: '#141414' }}>Find trusted costs and care information in minutes, on your own or with a caregiver.</p>
            <div className="flex flex-col md:flex-row md:items-center gap-3 md:gap-6 text-sm">
              <div>
                <div style={{ color: '#141414' }}>with funding from the</div>
                <div className="font-semibold">John A Hartford Foundation</div>
              </div>
              <button className="flex items-center gap-2 px-4 py-2 rounded-full border self-start" style={{ borderColor: '#0891B2' }}>
                <div className="w-8 h-8 rounded-full flex items-center justify-center" style={{ background: '#0891B2' }}>
                  <Play size={12} fill="white" style={{ color: 'white' }} />
                </div>
                <span className="text-sm">
                  Video: <span className="font-bold" style={{ color: '#3C3489' }}>How to use our tools</span>
                  <span className="ml-3">2 minutes</span>
                </span>
              </button>
            </div>
          </div>
          <div className="fh-hero-img w-full md:w-80 h-44 md:h-auto md:flex-shrink-0 overflow-hidden" style={{ background: '#F5F5F5' }}>
            {/* In the Vite build, swap HERO_IMG for "/hero.png" */}
            <img
              src={HERO_IMG}
              alt="Older adult at a laptop"
              className="w-full h-full"
              style={{ objectFit: 'cover', display: 'block' }}
            />
          </div>
        </div>

        {/* Alzheimer's callout */}
        <div className="flex flex-col md:flex-row md:items-stretch overflow-hidden" style={{ background: '#F3F3F3', border: '1px solid #E5E5E5' }}>
          <div className="fh-alz-img w-full h-32 md:h-auto md:flex-shrink-0 overflow-hidden" style={{ background: '#2A7F95' }}>
            {/* In the Vite build, swap ALZHEIMERS_IMG for "/alzheimers.png" */}
            <img
              src={ALZHEIMERS_IMG}
              alt="Hands holding the hand of a person with Alzheimer's"
              className="w-full h-full"
              style={{ objectFit: 'cover', display: 'block' }}
            />
          </div>
          <div className="flex items-center px-5 md:px-6 py-4 md:py-5 md:flex-1">
            <div>
              <h2 className="font-bold mb-2" style={{ fontSize: '22px', color: '#141414', lineHeight: '1.2' }}>
                Navigating Alzheimer's care
              </h2>
              <p style={{ fontSize: '15px', color: '#141414', lineHeight: '1.5', maxWidth: '480px' }}>
                Tools and trusted information to help you weigh treatment options, plan for years of care, and budget with confidence — for yourself or someone you love.
              </p>
            </div>
          </div>
          <div className="flex items-center px-5 md:px-6 py-4 md:py-5 md:min-w-[340px]">
            <div className="w-full">
              <ul className="space-y-1 mb-3 font-bold" style={{ fontSize: '15px', color: '#2A7F95', lineHeight: '1.4' }}>
                <li><a href="/alzheimers/resources.html" className="hover:underline">Resources</a></li>
                <li><a href="#" className="hover:underline">Alzheimer's disease treatment options</a></li>
                <li><a href="#" className="hover:underline">Decision aid</a></li>
                <li><a href="#" className="hover:underline">Total Treatment Cost Options</a></li>
              </ul>
              <a
                href="/alzheimers/"
                className="inline-block px-5 py-2 text-white font-medium rounded-full"
                style={{ background: '#2A7F95', fontSize: '14px' }}
              >
                More Information
              </a>
            </div>
          </div>
        </div>

        {/* Two main tool cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Shared Decision Making */}
          <div
            className="bg-white overflow-hidden"
            style={{ borderLeft: '6px solid #D14A2D' }}
          >
            <div className="p-6">
              <div className="flex items-center gap-3 mb-4">
                <DecisionIcon size={28} />
                <h2 className="text-xl font-bold">Shared Decision Making</h2>
              </div>
              <p className="text-sm mb-4" style={{ color: '#141414' }}>Weigh your treatment options, side by side</p>
              <div ref={conditionDropdownRef} className="relative mb-4">
                <button
                  type="button"
                  onClick={() => setConditionDropdownOpen(v => !v)}
                  className="w-full flex items-center justify-between px-4 py-3 rounded border text-left transition-colors"
                  style={{
                    background: '#F3F3F3',
                    borderColor: conditionDropdownOpen ? '#D14A2D' : '#E5E5E5',
                    color: '#141414',
                  }}
                >
                  <span className="text-sm">{selectedCondition || 'Select a Condition...'}</span>
                  <ChevronDown
                    size={18}
                    style={{
                      color: '#141414',
                      transform: conditionDropdownOpen ? 'rotate(180deg)' : 'none',
                      transition: 'transform 0.2s',
                    }}
                  />
                </button>
                {conditionDropdownOpen && (
                  <div
                    className="absolute top-full left-0 right-0 mt-1 bg-white border shadow-lg overflow-y-auto"
                    style={{ borderColor: '#D14A2D', maxHeight: '320px', zIndex: 20 }}
                  >
                    {CONDITIONS.map((condition) => {
                      const isSelected = selectedCondition === condition;
                      return (
                        <button
                          key={condition}
                          type="button"
                          onClick={() => {
                            setSelectedCondition(condition);
                            setConditionDropdownOpen(false);
                          }}
                          className="w-full text-left px-3 py-2 text-sm flex items-start gap-2 transition-colors"
                          style={{
                            color: '#141414',
                            background: isSelected ? '#FBE9E3' : 'white',
                          }}
                          onMouseEnter={(e) => { if (!isSelected) e.currentTarget.style.background = '#FDF5F2'; }}
                          onMouseLeave={(e) => { if (!isSelected) e.currentTarget.style.background = 'white'; }}
                        >
                          <span className="w-4 flex-shrink-0 pt-0.5" style={{ color: '#D14A2D' }}>
                            {isSelected ? '✓' : ''}
                          </span>
                          <span>{condition}</span>
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
              <div className="flex justify-end">
                <button
                  className="px-5 py-2 text-white font-medium rounded-full"
                  style={{ background: '#D14A2D', fontSize: '14px' }}
                >
                  Compare my options
                </button>
              </div>
              <div className="mt-5">
                <div className="font-bold mb-2" style={{ color: '#D14A2D', fontSize: '14px' }}>Decision Examples</div>
                <div className="flex flex-wrap gap-2">
                  {["Alzheimer's Disease Treatment Options", 'Type 2 Diabetes', 'Hip Replacement, Should I Have It?', 'Early-Stage Breast Cancer'].map(x => {
                    const isSelected = selectedCondition === x;
                    return (
                      <button
                        key={x}
                        type="button"
                        onClick={() => setSelectedCondition(x)}
                        className="px-3 py-1 rounded-full text-xs border transition-colors"
                        style={{
                          background: isSelected ? '#FBE9E3' : '#F3F3F3',
                          borderColor: isSelected ? '#D14A2D' : 'transparent',
                          color: isSelected ? '#D14A2D' : '#141414',
                        }}
                        onMouseEnter={(e) => { if (!isSelected) e.currentTarget.style.background = '#FDF5F2'; }}
                        onMouseLeave={(e) => { if (!isSelected) e.currentTarget.style.background = '#F3F3F3'; }}
                      >
                        {x}
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>

          {/* FH Total Treatment Cost */}
          <div
            className="bg-white overflow-hidden"
            style={{ borderLeft: '6px solid #3C3489' }}
          >
            <div className="p-6">
              <div className="flex items-center gap-3 mb-4">
                <MedicalIcon size={28} />
                <h2 className="text-xl font-bold">FH® Total Treatment Cost</h2>
              </div>
              <p className="text-sm mb-4" style={{ color: '#141414' }}>Personalized cost estimates for chronic conditions and major procedures.</p>
              <div className="flex gap-3 mb-4">
                <div className="w-24 flex-shrink-0">
                  <input
                    type="text"
                    inputMode="numeric"
                    maxLength={5}
                    value={zipValue}
                    onChange={(e) => setZipValue(e.target.value.replace(/[^0-9]/g, '').slice(0, 5))}
                    placeholder="Zip"
                    className="w-full px-3 py-3 rounded border text-sm outline-none"
                    style={{ background: '#F3F3F3', borderColor: '#E5E5E5', color: '#141414' }}
                  />
                </div>
                <div ref={procedureDropdownRef} className="relative flex-1">
                  <button
                    type="button"
                    onClick={() => setProcedureDropdownOpen(v => !v)}
                    className="w-full flex items-center justify-between px-4 py-3 rounded border text-left transition-colors"
                    style={{
                      background: '#F3F3F3',
                      borderColor: procedureDropdownOpen ? '#3C3489' : '#E5E5E5',
                      color: '#141414',
                    }}
                  >
                    <span className="text-sm truncate">
                      {selectedProcedure || 'Condition or Procedure...'}
                    </span>
                    <ChevronDown
                      size={18}
                      className="flex-shrink-0 ml-2"
                      style={{
                        color: '#141414',
                        transform: procedureDropdownOpen ? 'rotate(180deg)' : 'none',
                        transition: 'transform 0.2s',
                      }}
                    />
                  </button>
                  {procedureDropdownOpen && (
                    <div
                      className="absolute top-full left-0 right-0 mt-1 bg-white border shadow-lg overflow-y-auto"
                      style={{ borderColor: '#3C3489', maxHeight: '320px', zIndex: 20 }}
                    >
                      {PROCEDURES.map((procedure) => {
                        const isSelected = selectedProcedure === procedure;
                        return (
                          <button
                            key={procedure}
                            type="button"
                            onClick={() => {
                              setSelectedProcedure(procedure);
                              setProcedureDropdownOpen(false);
                            }}
                            className="w-full text-left px-3 py-2 text-sm flex items-start gap-2 transition-colors"
                            style={{
                              color: '#141414',
                              background: isSelected ? '#EDE9F5' : 'white',
                            }}
                            onMouseEnter={(e) => { if (!isSelected) e.currentTarget.style.background = '#F4F1F8'; }}
                            onMouseLeave={(e) => { if (!isSelected) e.currentTarget.style.background = 'white'; }}
                          >
                            <span className="w-4 flex-shrink-0 pt-0.5" style={{ color: '#3C3489' }}>
                              {isSelected ? '✓' : ''}
                            </span>
                            <span>{procedure}</span>
                          </button>
                        );
                      })}
                    </div>
                  )}
                </div>
              </div>
              <div className="flex justify-end">
                <button
                  className="px-5 py-2 text-white font-medium rounded-full"
                  style={{ background: '#3C3489', fontSize: '14px' }}
                >
                  See my estimate
                </button>
              </div>
              <div className="mt-5">
                <div className="font-bold mb-2" style={{ color: '#3C3489', fontSize: '14px' }}>Procedure Examples</div>
                <div className="flex flex-wrap gap-2">
                  {['Knee Replacement', 'Hyperlipidemia', 'Colonoscopy', 'Asthma', 'C-Section', "Alzheimer's Disease"].map(x => {
                    const isSelected = selectedProcedure === x;
                    return (
                      <button
                        key={x}
                        type="button"
                        onClick={() => setSelectedProcedure(x)}
                        className="px-3 py-1 rounded-full text-xs border transition-colors"
                        style={{
                          background: isSelected ? '#EDE9F5' : '#F3F3F3',
                          borderColor: isSelected ? '#3C3489' : 'transparent',
                          color: isSelected ? '#3C3489' : '#141414',
                        }}
                        onMouseEnter={(e) => { if (!isSelected) e.currentTarget.style.background = '#F4F1F8'; }}
                        onMouseLeave={(e) => { if (!isSelected) e.currentTarget.style.background = '#F3F3F3'; }}
                      >
                        {x}
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* FH Healthcare Toolkit banner — full-width horizontal */}
        <div className="flex flex-col md:flex-row md:items-stretch text-white" style={{ background: '#3C3489' }}>
          <div className="flex items-center gap-4 px-5 md:px-6 py-4" style={{ background: '#2E2870' }}>
            <PrintIcon size={40} />
            <div className="font-bold leading-tight" style={{ fontSize: '22px' }}>
              FH® Healthcare<br/>Toolkit
            </div>
          </div>
          <div className="flex items-center px-5 md:px-6 py-4 md:flex-1">
            <div className="leading-snug">
              <div className="font-bold mb-1" style={{ fontSize: '18px' }}>Download and Print</div>
              <div className="font-bold leading-tight" style={{ fontSize: '13px' }}>
                Checklists and Toolkits For Patients and Caregivers
              </div>
            </div>
          </div>
          <div className="flex flex-col justify-center px-5 md:px-6 py-4 md:min-w-[380px]">
            <div ref={checklistDropdownRef} className="relative w-full">
              <button
                type="button"
                onClick={() => setChecklistDropdownOpen(v => !v)}
                className="w-full flex items-center justify-between px-4 py-2.5 rounded border text-left transition-colors bg-white"
                style={{ borderColor: checklistDropdownOpen ? '#FFF' : '#E5E5E5' }}
              >
                <span className="text-sm font-bold" style={{ color: '#141414' }}>
                  {selectedChecklist || 'Select Checklist'}
                </span>
                <ChevronDown
                  size={16}
                  style={{
                    color: '#141414',
                    transform: checklistDropdownOpen ? 'rotate(180deg)' : 'none',
                    transition: 'transform 0.2s',
                  }}
                />
              </button>
              {checklistDropdownOpen && (
                <div
                  className="absolute top-full left-0 right-0 mt-1 bg-white border shadow-lg overflow-y-auto"
                  style={{ borderColor: '#3C3489', maxHeight: '280px', zIndex: 20 }}
                >
                  {CHECKLISTS.map((checklist) => {
                    const isSelected = selectedChecklist === checklist;
                    return (
                      <button
                        key={checklist}
                        type="button"
                        onClick={() => {
                          setSelectedChecklist(checklist);
                          setChecklistDropdownOpen(false);
                        }}
                        className="w-full text-left px-3 py-2 text-sm flex items-start gap-2 transition-colors"
                        style={{
                          color: '#141414',
                          background: isSelected ? '#EDE9F5' : 'white',
                        }}
                        onMouseEnter={(e) => { if (!isSelected) e.currentTarget.style.background = '#F4F1F8'; }}
                        onMouseLeave={(e) => { if (!isSelected) e.currentTarget.style.background = 'white'; }}
                      >
                        <span className="w-4 flex-shrink-0 pt-0.5" style={{ color: '#3C3489' }}>
                          {isSelected ? '✓' : ''}
                        </span>
                        <span>{checklist}</span>
                      </button>
                    );
                  })}
                </div>
              )}
            </div>

            <div className="flex flex-wrap items-center gap-2 mt-3">
              <span className="text-xs font-semibold mr-1">Jump to:</span>
              {['Shared Decision Making', 'Healthcare Navigation', 'Choosing a Provider'].map(label => (
                <button
                  key={label}
                  type="button"
                  onClick={() => {
                    const map = {
                      'Shared Decision Making': 'Shared Decision-Making Checklist for Patients',
                      'Healthcare Navigation': 'Healthcare Navigation Checklist for Patients',
                      'Choosing a Provider': 'Choosing a Healthcare Provider: Questions to Ask',
                    };
                    setSelectedChecklist(map[label]);
                  }}
                  className="text-xs px-3 py-1 rounded-full transition-colors"
                  style={{
                    background: 'rgba(255,255,255,0.18)',
                    color: '#FFF',
                    border: '0.5px solid rgba(255,255,255,0.5)',
                  }}
                  onMouseEnter={(e) => e.currentTarget.style.background = 'rgba(255,255,255,0.28)'}
                  onMouseLeave={(e) => e.currentTarget.style.background = 'rgba(255,255,255,0.18)'}
                >
                  {label}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Bottom two-column: Cost Lookup + Financial Health Literacy — separate cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white p-5 md:p-6" style={{ border: '1px solid #E5E5E5' }}>
            <h3 className="font-bold text-lg mb-3">Estimate Costs in Your Area</h3>
            <div className="flex items-center gap-3 mb-3">
              <MedicalCostIcon size={36} />
              <span className="font-bold" style={{ color: '#3C3489', fontSize: '18px', lineHeight: '1.25' }}>FH® Medical Cost Lookup Tool</span>
            </div>
            <div className="flex items-center gap-3" style={{ paddingTop: '50px' }}>
              <DentalCostIcon size={36} />
              <span className="font-bold" style={{ color: '#3C3489', fontSize: '18px', lineHeight: '1.25' }}>FH® Dental Cost Lookup Tool</span>
            </div>
          </div>
          <div className="bg-white p-5 md:p-6" style={{ border: '1px solid #E5E5E5' }}>
            <div className="flex items-start justify-between mb-3">
              <h3 className="font-bold text-lg leading-tight">Financial Health Literacy Guide</h3>
              <FinanceIcon size={56} />
            </div>
            <p className="text-sm mb-4" style={{ color: '#141414', lineHeight: '1.5' }}>
              Learn about steps you can take to prepare for and manage your healthcare costs.
            </p>
            <a
              href="https://fhfinancialliteracy.netlify.app/"
              target="_blank"
              rel="noopener noreferrer"
              className="inline-block px-4 py-2 text-white text-sm font-medium rounded-full mb-3"
              style={{ background: '#3C3489' }}
            >
              Explore the guide →
            </a>
            <div className="flex flex-wrap gap-2">
              {['Medicare', 'Medicaid', 'COBRA', 'Explanation of Benefits'].map(pill => (
                <span
                  key={pill}
                  className="px-3 py-1 rounded-full text-xs"
                  style={{ background: '#F3F3F3', color: '#141414' }}
                >
                  {pill}
                </span>
              ))}
            </div>
          </div>
        </div>

        <div className="text-xs text-center py-4" style={{ color: '#999' }}>
          Prototype · FAIR Health Consumer · Older Adults
        </div>
      </div>
    </div>
  );
}
